parameters.jsCode:
const output = $json.output;

// Strip markdown code fences
const cleanJson = output
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Parse JSON
const parsed = JSON.parse(cleanJson);

return [{
  json: {
    taylor_summary: parsed.ai_summary || '',
    taylor_char_count: parsed.character_count || '',
    taylor_flags: Array.isArray(parsed.quality_flags) 
      ? parsed.quality_flags.join('\n• ') 
      : parsed.quality_flags || '',
    taylor_brand_alignment: parsed.brand_alignment_score || 0,
    taylor_recommendation: parsed.recommendation || '',
    taylor_reasoning: parsed.reasoning || '',
    taylor_feedback: parsed.feedback_for_team || '',
    taylor_score: parsed.final_score || 0,
    // Pass through original data for Wait form
    post_copy: $json.post_copy || '',
    visual_direction: $json.visual_direction || ''
  }
}];
